/* ============================================================
   Full Stack Development Course - Application
   SPA routing, lessons, quizzes, progress, search, notes,
   highlights, bookmarks, accounts, forum, theme.
   Works online (Express API) and fully offline (localStorage + SW).
   ============================================================ */
'use strict';

/* MODULES (and COURSE_STATS) come from js/modules-data.js, generated by build-content.py */
const STORAGE_KEY = 'fs_course_state_v1';
const PASS_MARK = 0.7;

/* ---------- Helpers ---------- */
const $ = (id) => document.getElementById(id);
const esc = (s) => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const escapeHtml = esc;
const icon = (n, cls) => `<svg class="i ${cls || ''}" aria-hidden="true"><use href="#i-${n}"/></svg>`;
const pad = (n) => String(n).padStart(2, '0');
const byId = (id) => MODULES.find(m => m.id === id);
const COURSE = MODULES.filter(m => m.kind !== 'reference');      // numbered modules that count towards progress
const REFS = MODULES.filter(m => m.kind === 'reference');        // cheat sheets and look-up pages
const LESSONS = COURSE.filter(m => m.id !== 'exam');
const modLabel = (m) => m.kind === 'reference' ? 'Reference' : 'Module ' + pad(m.num);
const isModule = (id) => !!byId(id);
const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
function el(tag, cls, html) { const e = document.createElement(tag); if (cls) e.className = cls; if (html != null) e.innerHTML = html; return e; }

/* ---------- State ---------- */
function loadState() { try { return JSON.parse(localStorage.getItem(STORAGE_KEY)) || {}; } catch (e) { return {}; } }
function saveState(s, skipSync) {
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(s || state)); } catch (e) { console.warn('save failed', e); }
  if (!skipSync) scheduleSync();
}
let state = loadState();
['completed', 'quizScores', 'notes', 'highlights', 'capstone'].forEach(k => { if (!state[k] || typeof state[k] !== 'object') state[k] = {}; });
['prefs', 'challenges', 'projects', 'activity'].forEach(k => { if (!state[k] || typeof state[k] !== 'object') state[k] = {}; });
if (!Array.isArray(state.localForum)) state.localForum = [];
if (!Array.isArray(state.bookmarks)) state.bookmarks = [];
if (!(state.goal >= 1 && state.goal <= 7)) state.goal = 3;
if (!state.user) state.user = null;
if (!state.token) state.token = null;

const isCompleted = (id) => !!state.completed[id];
const getCurrentModule = () => (location.hash.replace('#', '') || 'home');
const navigateTo = (id) => { location.hash = id; };

/* ---------- API layer ---------- */
const hasServer = location.protocol === 'http:' || location.protocol === 'https:';
async function api(method, path, body) {
  if (!hasServer) { const e = new Error('offline-build'); e.network = true; throw e; }
  const headers = { 'Content-Type': 'application/json' };
  if (state.token) headers.Authorization = 'Bearer ' + state.token;
  const res = await fetch('/api' + path, { method, headers, body: body ? JSON.stringify(body) : undefined });
  if (!(res.headers.get('content-type') || '').includes('application/json')) { const e = new Error('No API'); e.network = true; throw e; }
  const data = await res.json();
  if (!res.ok) { const e = new Error(data.error || 'Request failed'); e.status = res.status; throw e; }
  return data;
}
let syncTimer = null;
function scheduleSync() { if (!state.token || !navigator.onLine) return; clearTimeout(syncTimer); syncTimer = setTimeout(pushSync, 1500); }
async function pushSync() {
  if (!state.token) return;
  try { await api('PUT', '/sync', { completed: state.completed, bookmarks: state.bookmarks, notes: state.notes, highlights: state.highlights, extra: { prefs: state.prefs, challenges: state.challenges, quizScores: state.quizScores, projects: state.projects, activity: state.activity, goal: state.goal } }); }
  catch (e) { if (e.status === 401) { state.token = null; saveState(state, true); } }
}
/* Merge progress from the server or an imported file into local state. Nothing is ever removed:
   completed things stay completed, scores keep the best value, activity keeps the larger count per day. */
function mergeProgress(d) {
  if (!d || typeof d !== 'object') return;
  const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
  const x = Object.assign({}, obj(d.extra), d.extra ? {} : d);   // an exported file is flat; the server nests the extras
  Object.keys(obj(d.completed)).forEach(k => { if (d.completed[k]) state.completed[k] = true; });
  (Array.isArray(d.bookmarks) ? d.bookmarks : []).forEach(b => { if (typeof b === 'string' && !state.bookmarks.includes(b)) state.bookmarks.push(b); });
  Object.keys(obj(d.notes)).forEach(k => { if (!state.notes[k] && typeof d.notes[k] === 'string') state.notes[k] = d.notes[k].slice(0, 20000); });
  Object.keys(obj(d.highlights)).forEach(k => {
    const mine = state.highlights[k] = state.highlights[k] || [];
    (Array.isArray(d.highlights[k]) ? d.highlights[k] : []).forEach(t => { if (typeof t === 'string' && !mine.includes(t)) mine.push(t); });
  });
  Object.keys(obj(x.challenges)).forEach(k => { if (x.challenges[k]) state.challenges[k] = true; });
  Object.keys(obj(x.prefs)).forEach(k => { if (!state.prefs[k]) state.prefs[k] = x.prefs[k]; });
  Object.keys(obj(x.quizScores)).forEach(m => {
    const mine = state.quizScores[m] = state.quizScores[m] || {};
    Object.keys(obj(x.quizScores[m])).forEach(q => { const v = +x.quizScores[m][q]; if (isFinite(v)) mine[q] = Math.max(mine[q] || 0, Math.min(100, v)); });
  });
  Object.keys(obj(x.projects)).forEach(id => {
    const theirs = obj(x.projects[id]), mine = state.projects[id];
    if (!PROJECTS.some(p => p.id === id)) return;
    const clean = { req: (Array.isArray(theirs.req) ? theirs.req : []).map(Boolean), stretch: (Array.isArray(theirs.stretch) ? theirs.stretch : []).map(Boolean), rubric: !!theirs.rubric,
      link: /^https?:\/\//i.test(theirs.link || '') ? String(theirs.link).slice(0, 300) : '', note: String(theirs.note || '').slice(0, 2000), done: !!theirs.done, doneAt: theirs.doneAt || null };
    if (!mine || (clean.done && !mine.done)) state.projects[id] = clean;
    else if (!mine.done && !mine.note && clean.note) mine.note = clean.note;
  });
  Object.keys(obj(x.activity)).forEach(k => { const v = +x.activity[k]; if (/^\d{4}-\d{2}-\d{2}$/.test(k) && v > 0) state.activity[k] = Math.max(state.activity[k] || 0, Math.min(v, 9999)); });
  if (x.goal >= 1 && x.goal <= 7 && !state.goalSet) state.goal = +x.goal;
}
async function pullSync() {
  const d = await api('GET', '/sync');
  mergeProgress(d);
  saveState(state, true);
  await pushSync();
}

/* ---------- Progress & sidebar ---------- */
const completedCount = () => COURSE.filter(m => state.completed[m.id]).length;
const progressPercent = () => overall().pct;
function toMin(t) {
  const m = /(\d+(?:\.\d+)?)(?:\s*[-\u2013]\s*(\d+(?:\.\d+)?))?\s*(h|min)/i.exec(t || '');
  if (!m) return 0;
  const n = parseFloat(m[2] || m[1]);
  return /^h/i.test(m[3]) ? n * 60 : n;
}
const fmtMin = (n) => n < 60 ? Math.round(n / 5) * 5 + ' min' : (Math.round(n / 6) / 10) + ' h';
const challengesDone = () => Object.keys(state.challenges).filter(k => state.challenges[k] && byId(k.split('.')[0])).length;
const projectDone = (id) => !!(state.projects[id] && state.projects[id].done);
function projectPct(p) {
  const st = state.projects[p.id];
  if (!st) return 0;
  if (st.done) return 100;
  return Math.round(((st.req || []).filter(Boolean).length + (st.rubric ? 1 : 0)) / (p.reqs + 1) * 100);
}
const projectStatus = (p) => projectDone(p.id) ? 'Complete' : (projectPct(p) > 0 ? 'In progress' : 'Not started');
/* Weighted overall progress: lessons 35%, challenges 20%, projects 30%, final exam 15%. */
const WEIGHTS = { lessons: .35, challenges: .20, projects: .30, exam: .15 };
function overall() {
  const chT = COURSE.reduce((a, m) => a + (m.ch || 0), 0);
  const parts = {
    lessons: { done: LESSONS.filter(m => state.completed[m.id]).length, total: LESSONS.length },
    challenges: { done: Math.min(challengesDone(), chT), total: chT },
    projects: { done: PROJECTS.filter(p => projectDone(p.id)).length, total: PROJECTS.length },
    exam: { done: examPassed() ? 1 : 0, total: 1 }
  };
  let f = 0;
  Object.keys(parts).forEach(k => { const q = parts[k]; q.w = WEIGHTS[k]; q.frac = q.total ? q.done / q.total : 0; f += q.w * q.frac; });
  return { parts, frac: f, pct: Math.round(f * 100) };
}
/* ---------- Activity (study days, streaks, weekly goal) ---------- */
const dayKey = (d) => { d = d || new Date(); return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); };
function logActivity(n) {
  const k = dayKey();
  state.activity[k] = (state.activity[k] || 0) + (n || 1);
  const keys = Object.keys(state.activity);
  if (keys.length > 200) keys.sort().slice(0, keys.length - 200).forEach(x => delete state.activity[x]);
}
function streaks() {
  const a = state.activity, d = new Date();
  if (!(a[dayKey(d)] > 0)) d.setDate(d.getDate() - 1);
  let cur = 0;
  while (a[dayKey(d)] > 0) { cur++; d.setDate(d.getDate() - 1); }
  const days = Object.keys(a).filter(k => a[k] > 0).sort();
  let best = 0, run = 0, prev = null;
  days.forEach(k => { const t = new Date(k + 'T00:00:00'); run = prev && Math.round((t - prev) / 864e5) === 1 ? run + 1 : 1; best = Math.max(best, run); prev = t; });
  return { cur, best, days: days.length };
}
function weekActive() {
  const d = new Date(); d.setDate(d.getDate() - ((d.getDay() + 6) % 7));
  let n = 0;
  for (let i = 0; i < 7; i++) { if (state.activity[dayKey(d)] > 0) n++; d.setDate(d.getDate() + 1); }
  return n;
}
function updateProgress() {
  const p = progressPercent();
  $('progressFill').style.width = p + '%';
  $('progressLabel').textContent = p + '%';
  $('progressBar').setAttribute('aria-valuenow', p);
}
function setCompleted(id, val) {
  if (val) state.completed[id] = true; else delete state.completed[id];
  saveState(state); renderSidebar(); updateProgress(); refreshActions();
}
function markCompleted(id) { if (!state.completed[id]) setCompleted(id, true); }

function renderSidebar() {
  const cur = getCurrentModule();
  const link = (href, inner, active, done) =>
    `<li><a class="nav-link ${active ? 'active' : ''}" href="#${href}" ${active ? 'aria-current="page"' : ''}>${inner}${done ? icon('check-circle', 'done-mark') : ''}</a></li>`;
  let html = `<ul>${link('home', icon('home', 'lead') + '<span>Overview</span>', cur === 'home')}` +
    link('progress', icon('target', 'lead') + '<span>My progress</span>', cur === 'progress') +
    link('projects', icon('award', 'lead') + '<span>Projects</span>', cur === 'projects', PROJECTS.length && PROJECTS.every(p => projectDone(p.id))) + '</ul>';
  const tracks = [...new Set(COURSE.map(m => m.track))];
  tracks.forEach(t => {
    html += `<div class="nav-group-title">${esc(t)}</div><ul>` +
      COURSE.filter(m => m.track === t).map(m => link(m.id, `<span class="num">${pad(m.num)}</span><span>${esc(m.title)}</span>`, cur === m.id, isCompleted(m.id))).join('') + '</ul>';
  });
  html += `<div class="nav-group-title">Reference</div><ul>` +
    link('reference', icon('layers', 'lead') + '<span>Reference library</span>', cur === 'reference') +
    REFS.map(m => link(m.id, icon('code', 'lead') + `<span>${esc(m.title)}</span>`, cur === m.id)).join('') +
    link('glossary', icon('book', 'lead') + '<span>Glossary</span>', cur === 'glossary') + '</ul>';
  html += `<div class="nav-group-title">Community</div><ul>` +
    link('forum', icon('chat', 'lead') + '<span>Discussion forum</span>', cur === 'forum') +
    link('profile', icon('user', 'lead') + `<span>${state.user ? 'Profile and grades' : 'Sign in'}</span>`, cur === 'profile') + '</ul>';
  $('moduleNav').innerHTML = html;
}

/* ---------- Page loading ---------- */
async function getModuleHtml(id) {
  if (window.__MODULES_HTML__ && window.__MODULES_HTML__[id]) return window.__MODULES_HTML__[id];
  const res = await fetch(`modules/${id}.html`);
  if (!res.ok) throw new Error('HTTP ' + res.status);
  return res.text();
}
function setPage(main, html, wide) {
  main.innerHTML = `<div class="page ${wide ? 'wide' : ''}">${html}</div>`;
  return main.firstElementChild;
}
const pageHead = (eyebrow, title, desc) =>
  `<header class="lesson-head"><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1>${desc ? `<p class="lesson-sum">${esc(desc)}</p>` : ''}</header>`;

let tocObserver = null;
async function loadPage(id) {
  const main = $('mainContent');
  main.setAttribute('aria-busy', 'true');
  if (tocObserver) { tocObserver.disconnect(); tocObserver = null; }
  if (id === 'home') renderHome(main);
  else if (id === 'forum') await renderForum(main);
  else if (id === 'glossary') await renderGlossary(main);
  else if (id === 'certificate') renderCertificate(main);
  else if (id === 'profile') renderProfile(main);
  else if (id === 'progress') renderProgress(main);
  else if (id === 'projects') renderProjects(main);
  else if (id === 'reference') renderReference(main);
  else if (isModule(id)) await renderModule(main, id);
  else setPage(main, `${pageHead('404', 'Page not found')}<p><a class="tap-link" href="#home">Return to the course overview</a></p>`, true);
  main.removeAttribute('aria-busy');
  window.scrollTo(0, 0);
  main.focus({ preventScroll: true });
  loadNotes();
  const m = byId(id);
  document.title = (m ? m.title : id === 'home' ? 'Overview' : id === 'progress' ? 'My progress' : id === 'reference' ? 'Reference library' : id[0].toUpperCase() + id.slice(1)) + ' | Full Stack Development Course';
}

async function renderModule(main, id) {
  const mod = byId(id);
  let html;
  try { html = await getModuleHtml(id); }
  catch (e) {
    setPage(main, `${pageHead(modLabel(mod), mod.title)}<div class="card"><p>This lesson is not cached yet. Connect to the internet once to download it for offline use.</p></div>`, true);
    return;
  }
  const page = setPage(main, '<article class="prose" id="article"></article><aside class="toc" aria-label="On this page"></aside>');
  const article = page.querySelector('article');
  article.innerHTML = html;
  buildLessonHead(article, mod);
  Quiz.mountAll(article, { onResult: (r) => onQuizResult(id, r), passNote: 'Passed. This module is marked complete.' });
  Widgets.enhance(article, widgetHooks());
  article.appendChild(buildPager(mod));
  applyHighlights(article, id);
  buildToc(article, page.querySelector('.toc'));
  state.viewed = state.viewed || {}; state.viewed[id] = true; logActivity(); saveState(state, true);
  if (pendingScroll) { const sel = pendingScroll; pendingScroll = null; setTimeout(() => { const t = article.querySelector(sel); if (t) t.scrollIntoView({ block: 'start' }); }, 120); }
}
let pendingScroll = null;
document.addEventListener('click', (e) => {
  const b = e.target.closest('[data-project]');
  if (!b) return;
  const sel = '.project[data-id="' + b.dataset.project + '"]', t = document.querySelector('#article ' + sel);
  if (t) { t.scrollIntoView({ behavior: 'smooth', block: 'start' }); } else pendingScroll = sel;
});

function buildLessonHead(article, mod) {
  const old = article.querySelector('header.lesson-head');
  const meta = old ? [...old.querySelectorAll('.lesson-meta span')].map(s => s.textContent.trim()).filter(t => t && !/^(Module\b|Reference$)/.test(t) && t !== mod.track) : [];
  const head = el('header', 'lesson-head',
    `<div class="eyebrow">${mod.kind === 'reference' ? 'Reference library' : 'Module ' + pad(mod.num) + ' &middot; ' + esc(mod.track)}</div>
     <h1>${esc(mod.title)}</h1>
     <p class="lesson-sum">${esc(mod.sum)}</p>
     <div class="meta">${meta.map(t => `<span class="chip">${esc(t)}</span>`).join('')}</div>
     <div class="lesson-actions">
       <button type="button" class="btn btn-secondary btn-sm" id="bmBtn"></button>
       ${mod.kind === 'reference' ? '' : '<button type="button" class="btn btn-secondary btn-sm" id="doneBtn"></button>'}
       ${(mod.pj || []).length ? `<button type="button" class="btn btn-secondary btn-sm" data-project="${esc(mod.pj[0])}">${icon('award')}Jump to the project</button>` : ''}
     </div>`);
  if (old) old.replaceWith(head); else article.prepend(head);
  $('bmBtn').addEventListener('click', toggleBookmark);
  if ($('doneBtn')) $('doneBtn').addEventListener('click', () => setCompleted(mod.id, !isCompleted(mod.id)));
  refreshActions();
}
function refreshActions() {
  const id = getCurrentModule();
  const bm = $('bmBtn'), dn = $('doneBtn');
  if (bm) {
    const on = state.bookmarks.includes(id);
    bm.className = 'btn btn-secondary btn-sm' + (on ? ' is-on' : '');
    bm.setAttribute('aria-pressed', on);
    bm.innerHTML = icon('bookmark', on ? 'filled' : '') + (on ? 'Bookmarked' : 'Bookmark');
  }
  if (dn) {
    const done = isCompleted(id);
    dn.className = 'btn btn-sm ' + (done ? 'btn-success-state' : 'btn-secondary');
    dn.setAttribute('aria-pressed', done);
    dn.innerHTML = icon('check-circle') + (done ? 'Completed' : 'Mark as complete');
  }
}
function toggleBookmark() {
  const id = getCurrentModule();
  if (!isModule(id)) return;
  const i = state.bookmarks.indexOf(id);
  if (i < 0) state.bookmarks.push(id); else state.bookmarks.splice(i, 1);
  saveState(state); refreshActions();
}

function buildPager(mod) {
  const list = mod.kind === 'reference' ? REFS : COURSE;
  const i = list.indexOf(mod), prev = list[i - 1], next = list[i + 1];
  const nav = el('nav', 'pager');
  nav.setAttribute('aria-label', 'Lesson navigation');
  nav.innerHTML =
    (prev ? `<a class="prev" href="#${prev.id}"><div class="dir">${icon('arrow-left')} Previous</div><div class="t">${esc(prev.title)}</div></a>`
          : `<a class="prev" href="#${mod.kind === 'reference' ? 'reference' : 'home'}"><div class="dir">${icon('arrow-left')} Back</div><div class="t">${mod.kind === 'reference' ? 'Reference library' : 'Course overview'}</div></a>`) +
    (next ? `<a class="next" href="#${next.id}"><div class="dir">Next ${icon('arrow-right')}</div><div class="t">${esc(next.title)}</div></a>`
          : `<a class="next" href="#${mod.kind === 'reference' ? 'reference' : 'progress'}"><div class="dir">Finish ${icon('arrow-right')}</div><div class="t">${mod.kind === 'reference' ? 'Reference library' : 'Your progress'}</div></a>`);
  return nav;
}

function buildToc(article, toc) {
  const targets = [...article.querySelectorAll('h2, .lab-box, .project, .quiz-slot[data-kind="test"]')];
  const items = targets.map((t, i) => {
    let text = t.textContent;
    if (t.classList.contains('lab-box')) { text = 'Hands-on lab'; if (!t.id) t.id = 'lab'; }
    else if (t.classList.contains('project')) { text = 'Project'; if (!t.id) t.id = 'project-' + i; }
    else if (t.classList.contains('quiz-slot')) { text = 'Module test'; if (!t.id) t.id = 'module-test'; }
    else if (!t.id) t.id = 'sec-' + (slug(text) || i);
    return { id: t.id, text, node: t };
  });
  if (items.length < 2) { toc.innerHTML = ''; return; }
  toc.innerHTML = `<div class="toc-title">On this page</div><ul>${items.map(it => `<li><a href="#" data-t="${it.id}">${esc(it.text)}</a></li>`).join('')}</ul>`;
  toc.querySelectorAll('a').forEach(a => a.addEventListener('click', e => {
    e.preventDefault();
    const t = document.getElementById(a.dataset.t);
    if (t) t.scrollIntoView({ behavior: 'smooth', block: 'start' });   // keeps the #module hash intact
  }));
  if (!('IntersectionObserver' in window)) return;
  const setActive = (id) => toc.querySelectorAll('a').forEach(a => a.classList.toggle('active', a.dataset.t === id));
  setActive(items[0].id);
  tocObserver = new IntersectionObserver(entries => {
    entries.forEach(en => { if (en.isIntersecting) setActive(en.target.id); });
  }, { rootMargin: '-90px 0px -65% 0px' });
  items.forEach(it => tocObserver.observe(it.node));
}

/* ---------- Learning services: language preference, quiz results, challenges ---------- */
const PREF_DEFAULT_LANG = 'javascript';
const getLang = () => (state.prefs && state.prefs.lang) || PREF_DEFAULT_LANG;
function setLang(lang, focus) {
  state.prefs.lang = lang; saveState(state);
  const sel = $('langSel'); if (sel) sel.value = lang;
  Widgets.applyLang(lang, focus);
}
const bestScore = (mod, quizId) => { const v = state.quizScores[mod] && state.quizScores[mod][quizId || mod]; return typeof v === 'number' ? v : null; };
const checkpointScores = (mod) => Object.keys(state.quizScores[mod] || {}).filter(k => k !== mod).map(k => state.quizScores[mod][k]);
function onQuizResult(modId, r) {
  const rec = state.quizScores[modId] = state.quizScores[modId] || {};
  rec[r.id] = Math.max(r.pct, rec[r.id] || 0);
  const note = r.kind === 'test' && r.pass;
  if (note) markCompleted(modId);
  logActivity(r.kind === 'test' ? 3 : 1);
  saveState(state);
  if (state.token) api('POST', `/quizzes/${encodeURIComponent(modId)}/attempts`, { quizId: r.id, score: r.pct }).catch(() => {});
}
const challengeKey = (id) => id;
const isChallengeDone = (id) => !!state.challenges[id];
function onChallengeDone(id) { if (!state.challenges[id]) { state.challenges[id] = true; logActivity(2); saveState(state); updateProgress(); } }
function onProjectChange(id, data, kind) {
  state.projects[id] = data;
  logActivity(kind === 'finish' ? 5 : 1);
  saveState(state); updateProgress(); renderSidebar();
}
function widgetHooks() {
  return {
    getLang, setLang, isDone: isChallengeDone, onChallenge: onChallengeDone,
    getPrefs: () => state.prefs, setPrefs: (a) => { Object.assign(state.prefs, a); saveState(state); },
    getScores: () => ({ basics: bestScore('basics') }),
    getProject: (id) => state.projects[id] || null, onProject: onProjectChange
  };
}

/* ---------- Notes ---------- */
function loadNotes() {
  const id = getCurrentModule();
  $('notesTitle').textContent = isModule(id) ? `Notes: ${byId(id).title}` : 'Notes';
  $('notesTextarea').value = state.notes[id] || '';
}
let notesTimer;
function saveNotes() {
  state.notes[getCurrentModule()] = $('notesTextarea').value;
  saveState(state);
  $('notesStatus').textContent = 'Saved';
  clearTimeout(notesTimer); notesTimer = setTimeout(() => { $('notesStatus').textContent = ''; }, 1500);
}

/* ---------- Highlights ---------- */
function applyHighlights(root, modId) {
  (state.highlights[modId] || []).forEach(text => {
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode: n => n.parentElement.closest('mark.hl, script, textarea, button, pre, .quiz-slot, .demo') ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT
    });
    let n;
    while ((n = walker.nextNode())) {
      const i = n.nodeValue.indexOf(text);
      if (i < 0) continue;
      const r = document.createRange(); r.setStart(n, i); r.setEnd(n, i + text.length);
      wrapHighlight(r); break;
    }
  });
}
function wrapHighlight(range) {
  const m = document.createElement('mark');
  m.className = 'hl'; m.title = 'Click to remove highlight';
  range.surroundContents(m);
}
function initHighlighting() {
  const btn = $('hlBtn'), main = $('mainContent');
  let pending = null;
  function check() {
    const sel = window.getSelection();
    if (!sel || sel.isCollapsed || !sel.rangeCount || !isModule(getCurrentModule())) { btn.classList.add('hidden'); return; }
    const r = sel.getRangeAt(0), text = sel.toString().trim();
    if (!text || text.length > 300 || r.startContainer !== r.endContainer || r.startContainer.nodeType !== 3 ||
        !main.contains(r.startContainer) || r.startContainer.parentElement.closest('mark.hl, textarea, pre, .quiz-slot, .demo, button')) { btn.classList.add('hidden'); return; }
    pending = { range: r.cloneRange(), text: sel.toString() };
    const rect = r.getBoundingClientRect();
    btn.style.top = Math.max(64, rect.top - 44) + 'px';
    btn.style.left = Math.min(window.innerWidth - 130, Math.max(8, rect.left)) + 'px';
    btn.classList.remove('hidden');
  }
  document.addEventListener('mouseup', () => setTimeout(check, 10));
  document.addEventListener('keyup', e => { if (e.key.startsWith('Arrow') || e.key === 'Shift') check(); });
  document.addEventListener('touchend', () => setTimeout(check, 300));
  btn.addEventListener('mousedown', e => e.preventDefault());
  btn.addEventListener('click', () => {
    if (!pending) return;
    const id = getCurrentModule();
    wrapHighlight(pending.range);
    (state.highlights[id] = state.highlights[id] || []).push(pending.text);
    saveState(state);
    window.getSelection().removeAllRanges();
    btn.classList.add('hidden'); pending = null;
  });
  main.addEventListener('click', e => {
    const m = e.target.closest('mark.hl');
    if (!m) return;
    const id = getCurrentModule(), t = m.textContent, arr = state.highlights[id] || [], i = arr.indexOf(t);
    if (i >= 0) arr.splice(i, 1);
    saveState(state);
    m.replaceWith(document.createTextNode(t)); main.normalize();
  });
}

/* ---------- Search ---------- */
const SEARCH_INDEX = [];
async function buildSearchIndex() {
  for (const m of MODULES) {
    try {
      const html = (await getModuleHtml(m.id)).replace(/<\/(p|li|h\d|div|span|td|th|pre|code)>/g, '$& ');
      const doc = new DOMParser().parseFromString(html, 'text/html');
      doc.querySelectorAll('script, .lang-tag, .lesson-meta').forEach(s => s.remove());
      SEARCH_INDEX.push({ id: m.id, title: m.title, num: m.num, text: doc.body.textContent.replace(/\s+/g, ' ') });
    } catch (e) { SEARCH_INDEX.push({ id: m.id, title: m.title, num: m.num, text: '' }); }
  }
  const q = $('searchInput').value; if (q) doSearch(q);
}
function markQ(text, q) {
  const i = text.toLowerCase().indexOf(q);
  return i < 0 ? esc(text) : esc(text.slice(0, i)) + '<mark>' + esc(text.slice(i, i + q.length)) + '</mark>' + esc(text.slice(i + q.length));
}
function doSearch(raw) {
  const q = raw.trim().toLowerCase(), box = $('searchResults');
  if (!q) { box.classList.remove('show'); box.innerHTML = ''; return; }
  const src = SEARCH_INDEX.length ? SEARCH_INDEX : MODULES.map(m => ({ id: m.id, title: m.title, num: m.num, text: '' }));
  const hits = [];
  src.forEach(r => {
    const inTitle = r.title.toLowerCase().includes(q), idx = r.text.toLowerCase().indexOf(q);
    if (inTitle || idx >= 0) {
      const snip = idx >= 0 ? (idx > 40 ? '\u2026' : '') + r.text.slice(Math.max(0, idx - 40), idx + 90) + '\u2026' : byId(r.id).sum;
      hits.push({ r, snip, score: (inTitle ? 2 : 0) + (idx >= 0 ? 1 : 0) });
    }
  });
  hits.sort((a, b) => b.score - a.score || a.r.num - b.r.num);
  box.innerHTML = hits.length
    ? hits.slice(0, 8).map(h => `<a href="#${h.r.id}"><div class="sr-title">${byId(h.r.id).kind === 'reference' ? 'Ref' : pad(h.r.num)} &middot; ${markQ(h.r.title, q)}</div><div class="sr-snippet">${markQ(h.snip, q)}</div></a>`).join('')
    : `<div class="sr-empty">No results for &ldquo;${esc(raw.trim())}&rdquo;</div>`;
  box.classList.add('show');
}

