const barHtml = (pct, label) => `<div class="progress-bar" role="img" aria-label="${esc(label)}"><div class="fill" style="width:${pct}%"></div></div>`;

function ringSvg(pct) {
  const r = 54, c = 2 * Math.PI * r;
  return `<svg class="ring" viewBox="0 0 140 140" role="img" aria-label="Overall progress ${pct} percent"><circle class="ring-bg" cx="70" cy="70" r="${r}"/><circle class="ring-fg"${pct ? "" : " hidden"} cx="70" cy="70" r="${r}" stroke-dasharray="${(c * pct / 100).toFixed(1)} ${c.toFixed(1)}" transform="rotate(-90 70 70)"/><text x="70" y="68" text-anchor="middle" class="ring-num">${pct}%</text><text x="70" y="90" text-anchor="middle" class="ring-sub">complete</text></svg>`;
}
function heatmapHtml() {
  const WEEKS = 16, today = new Date(); today.setHours(0, 0, 0, 0);
  const start = new Date(today); start.setDate(start.getDate() - ((today.getDay() + 6) % 7) - (WEEKS - 1) * 7);
  let cells = '', total = 0;
  for (let i = 0; i < WEEKS * 7; i++) {
    const d = new Date(start); d.setDate(start.getDate() + i);
    const n = state.activity[dayKey(d)] || 0, future = d > today;
    if (!future) total += n > 0 ? 1 : 0;
    const lvl = future ? 'f' : n === 0 ? 0 : n < 3 ? 1 : n < 6 ? 2 : n < 10 ? 3 : 4;
    cells += `<i class="hm l${lvl}" title="${d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}: ${n ? n + ' action' + (n === 1 ? '' : 's') : 'no activity'}"></i>`;
  }
  return `<div class="heat" role="img" aria-label="Study activity for the last ${WEEKS} weeks: ${total} active days">${cells}</div>
    <div class="heat-legend" aria-hidden="true"><span>Less</span><i class="hm l0"></i><i class="hm l1"></i><i class="hm l2"></i><i class="hm l3"></i><i class="hm l4"></i><span>More</span></div>`;
}
function nextSteps() {
  const out = [];
  PROJECTS.forEach(p => { if (!projectDone(p.id) && projectPct(p) > 0) out.push({ kind: 'Continue', href: p.mod, project: p.id, title: p.title, why: `Project in progress: ${projectPct(p)}% of the checklist is done.` }); });
  recommendations().filter(r => r.kind === 'next').forEach(r => out.push({ kind: 'Up next', href: r.mod.id, title: `${pad(r.mod.num)}. ${r.mod.title}`, why: r.why }));
  const ready = PROJECTS.find(p => isCompleted(p.mod) && !projectDone(p.id) && projectPct(p) === 0);
  if (ready) out.push({ kind: 'Build', href: ready.mod, project: ready.id, title: ready.title, why: 'You finished this module. Put it to work in a project.' });
  recommendations().filter(r => r.kind === 'review').slice(0, 2).forEach(r => out.push({ kind: 'Review', href: r.mod.id, title: `${pad(r.mod.num)}. ${r.mod.title}`, why: r.why }));
  return out.slice(0, 5);
}
