/* ---------- Glossary + certificate ---------- */
async function renderGlossary(main) {
  let body = '';
  try { body = await getModuleHtml('glossary'); } catch (e) { body = '<p>The glossary is not cached yet. Connect once to download it for offline use.</p>'; }
  const cats = window.GLOSS_CATS || [];
  setPage(main, `${pageHead('Reference', 'Glossary', 'Plain-English definitions of the terms developers use every day. Terms with a dotted underline in lessons open a short definition.')}
    <div class="gl-search"><label class="label" for="glFilter">Filter terms</label><input id="glFilter" class="field" type="search" placeholder="Type a word, for example API" autocomplete="off"></div>
    <div class="gl-cats" role="group" aria-label="Filter by topic"><button type="button" class="chip-btn" aria-pressed="true" data-cat="">All</button>${cats.map(c => `<button type="button" class="chip-btn" aria-pressed="false" data-cat="${esc(c)}">${esc(c)}</button>`).join('')}</div>
    <p class="gl-count" id="glCount" role="status" aria-live="polite"></p>
    <div id="glBody">${body}</div>`, true);
  let cat = '';
  const apply = () => {
    const q = $('glFilter').value.trim().toLowerCase();
    let n = 0;
    document.querySelectorAll('#glBody .gl-item').forEach(i => {
      const hit = (!cat || i.dataset.cat === cat) && (!q || i.textContent.toLowerCase().includes(q));
      i.hidden = !hit; if (hit) n++;
    });
    document.querySelectorAll('#glBody .gl-letter').forEach(l => { let x = l.nextElementSibling, any = false; while (x && !x.classList.contains('gl-letter')) { if (!x.hidden) any = true; x = x.nextElementSibling; } l.hidden = !any; });
    $('glCount').textContent = (q || cat) ? (n ? `${n} term${n === 1 ? '' : 's'} shown` : 'No terms match') : `${n} terms`;
  };
  $('glFilter').addEventListener('input', apply);
  document.querySelectorAll('.gl-cats .chip-btn').forEach(b => b.addEventListener('click', () => {
    cat = b.dataset.cat;
    document.querySelectorAll('.gl-cats .chip-btn').forEach(x => x.setAttribute('aria-pressed', x === b));
    apply();
  }));
  apply();
}
const examPassed = () => (bestScore('exam') || 0) >= 70;
